export interface AssetDemo {
  id: string;
  state?: string;
  /** the module the asset lives in (repo-relative from studio/src) */
  module: string;
  note?: string;
  /** what in this still is still a stand-in (empty = none) */
  standin?: string;
  draw: (fb: Buf) => void;
}
export const DEMOS: AssetDemo[] = [];
const D = (d: AssetDemo) => { DEMOS.push(d); };
const M = 'shared/pixel/';
/** a sheet backdrop for cast drawings: the show's night navy with a floor line */
const bench = (fb: Buf, c0 = PAL.N2, c1 = PAL.N1) => { for (let y = 0; y < 203; y++) for (let x = 0; x < 480; x++) fb.set(x, y, y < 150 ? (bayer(x, y) < 0.3 ? c1 : c0) : PAL.N1); rect(0, 150, 480, 1, fb.ink(PAL.N4)); };
const label = (fb: Buf, s: string, x: number, y: number) => text(fb, s, x, y, PAL.N6);
const bustAt = (fb: Buf, im: Img, x: number, y = 14, flip = false) => putBustCut(fb, im, x, y, 203, flip);

